SELECT 
FROM tianquan_oauth.oauth_authorization
WHERE tenant_id = #{tenantId} AND principal_name = #{principalName}
  AND status = #{status} AND id > #{afterId} AND deleted_at IS NULL
ORDER BY id ASC
LIMIT #{limit}

SELECT 
FROM tianquan_oauth.oauth_authorization
WHERE tenant_id = #{tenantId} AND absolute_expires_at <= #{expiresBefore}
  AND id > #{afterId} AND deleted_at IS NULL
ORDER BY id ASC
LIMIT #{limit}

SELECT FROM tianquan_oauth.oauth_authorization WHERE tenant_id = #{tenantId} AND deleted_at IS NULL AND id IN
#{id}
ORDER BY id ASC

mapper.update:
UPDATE tianquan_oauth.oauth_authorization
SET status = #{po.status}, revoked_at = #{po.revokedAt}, version = #{po.version},
    update_user_id = #{po.updateUserId}, update_time = #{po.updateTime}
WHERE tenant_id = #{tenantId} AND id = #{po.id} AND client_pk = #{po.clientPk}
  AND principal_name = #{po.principalName} AND principal_type = #{po.principalType}
  AND grant_type = #{po.grantType} AND version = #{expectedVersion} AND deleted_at IS NULL

UPDATE tianquan_oauth.oauth_authorization
SET deleted_at = CURRENT_TIMESTAMP AT TIME ZONE 'UTC', version = version + 1,
    update_user_id = #{po.updateUserId}, update_time = #{po.updateTime}
WHERE tenant_id = #{tenantId} AND id = #{po.id}
  AND version = #{expectedVersion} AND deleted_at IS NULL
